package com.magraoxx.eichattv;

import android.Manifest;import android.app.Activity;import android.content.Intent;import android.content.pm.PackageManager;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.os.Bundle;import android.provider.Settings;import android.speech.*;import android.speech.tts.TextToSpeech;import android.view.*;import android.widget.*;import java.util.*;

public class MainActivity extends Activity implements RecognitionListener{
 private static final int REQ_MIC=1001;private TextView status,caption,micText;private ProgressBar meter;private SpeechRecognizer sr;private TextToSpeech tts;private CommandEngine engine;private OpenAiClient ai;private ChatGptAuth auth;private boolean pending,retry;private float peak=-20f;
 @Override public void onCreate(Bundle b){super.onCreate(b);engine=new CommandEngine(this);ai=new OpenAiClient(this);auth=new ChatGptAuth(this);buildUi();initTts();initSpeech();if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},REQ_MIC);if(getIntent()!=null&&getIntent().getBooleanExtra("start_listening",false))startListening();}
 private TextView text(String s,float z){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(z);return v;}
 private GradientDrawable bg(int c,float r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(r);return g;}
 private Button button(String s,View.OnClickListener l){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(17);b.setFocusable(true);b.setOnClickListener(l);return b;}
 private void buildUi(){FrameLayout root=new FrameLayout(this);root.setBackgroundColor(Color.rgb(12,14,18));LinearLayout center=new LinearLayout(this);center.setOrientation(LinearLayout.VERTICAL);center.setGravity(Gravity.CENTER);center.setPadding(70,50,70,50);FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(-1,-1);root.addView(center,cp);
 TextView logo=text("Ei Chat",42);logo.setGravity(Gravity.CENTER);logo.setTypeface(null,1);center.addView(logo,new LinearLayout.LayoutParams(-1,-2));caption=text("Seu assistente na TV",20);caption.setGravity(Gravity.CENTER);caption.setTextColor(Color.LTGRAY);center.addView(caption,new LinearLayout.LayoutParams(-1,-2));
 LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(38,28,38,28);card.setBackground(bg(Color.rgb(30,33,40),30));LinearLayout.LayoutParams cardp=new LinearLayout.LayoutParams(-1,-2);cardp.setMargins(0,45,0,20);center.addView(card,cardp);status=text("Diga “Ei Chat” ou pressione OUVIR",26);status.setGravity(Gravity.CENTER);card.addView(status,new LinearLayout.LayoutParams(-1,-2));micText=text("●  pronto para ouvir",17);micText.setGravity(Gravity.CENTER);micText.setPadding(0,18,0,8);card.addView(micText,new LinearLayout.LayoutParams(-1,-2));meter=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);meter.setMax(100);meter.setProgress(0);card.addView(meter,new LinearLayout.LayoutParams(-1,12));
 Button listen=button("🎤  OUVIR",v->startListening());LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(360,70);bp.gravity=Gravity.CENTER;bp.setMargins(0,22,0,8);center.addView(listen,bp);Button settings=button("Configurações / diagnóstico",v->showDiagnostics());LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(360,60);sp.gravity=Gravity.CENTER;center.addView(settings,sp);setContentView(root);}
 private void showDiagnostics(){status.setText("Diagnóstico\n"+TvMicrophone.report(this)+"\nChatGPT: "+auth.accountLabel()+"\nPico: "+Math.round(peak)+" dB");caption.setText("Ei Chat • diagnóstico");}
 private void initTts(){tts=new TextToSpeech(this,x->{if(x==TextToSpeech.SUCCESS){tts.setLanguage(new Locale("pt","BR"));tts.setSpeechRate(1.02f);}});}
 private void initSpeech(){try{if(SpeechRecognizer.isRecognitionAvailable(this)){sr=SpeechRecognizer.createSpeechRecognizer(this);sr.setRecognitionListener(this);}}catch(Throwable x){sr=null;}}
 private Intent speechIntent(){Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,"pt-BR");i.putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,true);i.putExtra(RecognizerIntent.EXTRA_MAX_RESULTS,5);return i;}
 private void startListening(){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){pending=true;requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},REQ_MIC);return;}if(sr==null)initSpeech();if(sr==null){status.setText("Reconhecimento de voz indisponível nesta TV.");return;}try{sr.cancel();peak=-20;meter.setProgress(0);caption.setText("Ei Chat • ouvindo");status.setText("Estou ouvindo…");micText.setText(TvMicrophone.findBuiltIn(this)!=null?"●  microfone interno da TV detectado":"●  usando entrada fornecida pela TV");sr.startListening(speechIntent());}catch(Throwable x){status.setText("Não consegui iniciar o microfone: "+x.getMessage());}}
 private void handle(String q){retry=false;caption.setText("Você disse");status.setText("“"+q+"”");CommandEngine.Result r=engine.execute(q);if(r.handled){caption.setText("Ei Chat");status.setText(r.message);if(!r.success)speak(r.message);return;}caption.setText("Ei Chat • pensando");status.setText("Pensando…");ai.ask(q,new OpenAiClient.Callback(){public void onSuccess(String x){runOnUiThread(()->{caption.setText("Ei Chat");status.setText(x);speak(x);});}public void onError(String x){runOnUiThread(()->{caption.setText("Ei Chat");status.setText(x);speak(x);});}});}
 private void speak(String x){if(tts!=null&&x!=null&&!x.trim().isEmpty())tts.speak(x,TextToSpeech.QUEUE_FLUSH,null,"ei_chat");}
 public void onReadyForSpeech(Bundle b){status.setText("Pode falar");}public void onBeginningOfSpeech(){status.setText("Ouvindo você…");}public void onRmsChanged(float x){peak=Math.max(peak,x);int l=Math.max(0,Math.min(100,Math.round((x+2)*8)));meter.setProgress(l);micText.setText("●  ouvindo  •  "+Math.round(x)+" dB");}public void onBufferReceived(byte[] b){}public void onEndOfSpeech(){caption.setText("Ei Chat • entendendo");status.setText("Entendendo…");}public void onError(int e){if(e==SpeechRecognizer.ERROR_NO_MATCH&&!retry){retry=true;status.postDelayed(this::startListening,600);return;}caption.setText("Ei Chat");status.setText(e==SpeechRecognizer.ERROR_SPEECH_TIMEOUT?"Não ouvi nada. Tente novamente.":"Não consegui entender. Tente novamente.");micText.setText("●  pronto para ouvir");}public void onResults(Bundle b){ArrayList<String> m=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(m!=null&&!m.isEmpty())handle(m.get(0));}public void onPartialResults(Bundle b){ArrayList<String> m=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(m!=null&&!m.isEmpty())status.setText("“"+m.get(0)+"”");}public void onEvent(int e,Bundle b){}
 @Override public void onRequestPermissionsResult(int c,String[] p,int[] g){super.onRequestPermissionsResult(c,p,g);if(c==REQ_MIC&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED&&pending){pending=false;startListening();}}
 @Override protected void onDestroy(){if(sr!=null)sr.destroy();if(tts!=null)tts.shutdown();super.onDestroy();}
}
